<?php
require_once '../config/crud_service.php';require_role('admin');require_once '../includes/crud.php';$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{save_user($_POST);flash('success','Akun berhasil disimpan. Perubahan status, identitas atau password membatalkan sesi lama.');redirect('users.php');}catch(Throwable $e){$error=operation_error($e);$edit=$_POST;}}
elseif(isset($_GET['edit'])){$q=db()->prepare('SELECT id_user,username,role,id_referensi,status FROM users WHERE id_user=?');$q->execute([input_id($_GET,'edit')]);$edit=$q->fetch();if(!$edit)not_found();}
$search=input_text($_GET,'q',100,false);$role=input_text($_GET,'role',30,false);$status=input_text($_GET,'status',10,false);$roles=['admin'=>'Admin','guru'=>'Guru','kepala_sekolah'=>'Kepala Sekolah','siswa'=>'Siswa'];if($role!==''&&!isset($roles[$role]))throw new InputError('Role tidak valid.');if(!in_array($status,['','aktif','nonaktif'],true))throw new InputError('Status tidak valid.');
$where=[];$args=[];if($search!==''){$where[]='(username LIKE ? OR id_referensi LIKE ?)';$args=['%'.$search.'%','%'.$search.'%'];}if($role!==''){$where[]='role=?';$args[]=$role;}if($status!==''){$where[]='status=?';$args[]=$status;}$filter=$where?' WHERE '.implode(' AND ',$where):'';
$q=db()->prepare('SELECT COUNT(*) FROM users'.$filter);$q->execute($args);$total=(int)$q->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);$q=db()->prepare('SELECT id_user,username,role,id_referensi,status FROM users'.$filter." ORDER BY id_user LIMIT 20 OFFSET $offset");$q->execute($args);$rows=$q->fetchAll();
$page_title='Manajemen Akun';$crud_ui=true;require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><div class="crud-toolbar"><h2>Manajemen Akun</h2><a class="btn btn-outline-dark" href="users.php">Akun baru</a></div>
<p class="crud-note">Tidak ada password default. Referensi wajib cocok dengan guru/siswa aktif. Administrator aktif terakhir dilindungi; akun dinonaktifkan tanpa menghapus arsip.</p>
<?php if($error):?><div role="alert" class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<form method="post" class="card p-3 mb-4 crud-grid"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id_user" value="<?=e($edit['id_user']??'')?>">
<?php crud_field('username','Username',$edit['username']??'');crud_field('role','Role',$edit['role']??'',$roles);crud_field('id_referensi','ID Guru / NIS',$edit['id_referensi']??'',null,'text',false);crud_field('status','Status',$edit['status']??'aktif',['aktif'=>'Aktif','nonaktif'=>'Nonaktif']);crud_field('password',$edit?'Password baru (kosong = tetap)':'Password baru','',null,'password',!$edit);?><button class="btn btn-dark">Simpan Akun</button></form>
<form method="get" class="card p-3 mb-4 crud-grid"><?php crud_field('q','Cari username / referensi',$search,null,'search',false);crud_field('role','Role',$role,$roles,'text',false);crud_field('status','Status',$status,['aktif'=>'Aktif','nonaktif'=>'Nonaktif'],'text',false);?><button class="btn btn-dark">Terapkan filter</button></form>
<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Username</th><th>Role</th><th>Referensi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['username'])?></td><td><?=e(role_label($row['role']))?></td><td><?=e($row['id_referensi'])?></td><td><?=e($row['status'])?></td><td><div class="crud-actions"><a class="btn btn-outline-dark" href="?edit=<?=$row['id_user']?>">Edit</a><?php crud_status_actions('id_user',$row['id_user'],$row['status']);?></div></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></div><?php require '../includes/footer.php';
